import {
  defaultSlackAuth,
  extractGithubPrRef,
  type SlackMessageHandler,
  slackChannel,
} from "@grok/agent-sdk/channels/slack";
import { loadPrFiles } from "../lib/pr-first-pass.js";
import { REPOS, watches } from "../lib/repos.js";

const watch: string[] = [];

const clear = {
  "pr/meta.md": "",
  "pr/diff.patch": "",
  "pr/head.sha": "",
};

const handleSlack: SlackMessageHandler = async (ctx, message) => {
  const auth = defaultSlackAuth(message, ctx);
  if (auth === null) {
    return null;
  }

  const pr = extractGithubPrRef(message.markdown);
  if (pr === undefined) {
    return { auth };
  }

  const title = `Security Help ${pr.label}`;
  const fullName = `${pr.owner}/${pr.repo}`;
  if (!watches(fullName)) {
    return {
      auth,
      title,
      workspaceFiles: clear,
      context: [`Security help can only fetch ${REPOS.join(", ")} (got ${fullName}).`],
    };
  }

  const loaded = await loadPrFiles({
    github: ctx.host.github,
    ref: pr,
  });
  return {
    auth,
    title,
    workspaceFiles: loaded ?? clear,
    context:
      loaded === undefined
        ? ["Could not fetch the pull request. Connect GitHub or check the URL."]
        : undefined,
  };
};

export default slackChannel({
  envPrefix: "SECURITY_HELP",
  engagement: {
    channelPosts:
      watch.length === 0
        ? undefined
        : {
            allow: watch,
            posts: "top-level" as const,
          },
  },
  onAppMention: handleSlack,
  onDirectMessage: handleSlack,
  onChannelPost: watch.length === 0 ? undefined : handleSlack,
  suggestedPrompts: [
    {
      title: "Look at a PR",
      message: "First look at https://github.com/owner/repo/pull/1",
    },
    {
      title: "How urgent",
      message: "How urgent is this?",
    },
    {
      title: "Ask for context",
      message: "What else do we need before answering?",
    },
  ],
  suggestedPromptsTitle: "Ask security",
});
